NEW_FILES = []
SENTINELS = {'data/objects_config.json': '        "_declared": "The drawer\'s rows, by slug, in order outward from the Sun. Every row except the Sun can be ticked, one at a time, and ticking a row also opens it. A GROUP row (group, label) gathers the body rows that name it in their in field, listed after it: it is always listed, folded shut, and a tap folds it open to show them or shut again; it ticks nothing, and once one of its bodies is ticked its Reset unticks them all. There is no See more and nothing ticks many bodies at once: Tony\'s rulings of 2026-10-24 (L-477), the visitor builds the view one body at a time; order a lists its bodies by their served semi-major axis, nearest first, and without it they keep the order here (the comets, by their designations, the order they were discovered in; the spacecraft, by launch). Each group of small bodies is JPL\'s own class for its bodies (its Small-Body Database), one row per class, the comets\' after the Sun and the near-Earth asteroids\' among the planets where their orbits put them: Aten (orbits smaller than Earth\'s) after Venus, Apollo (larger than Earth\'s, crossing it) and Amor (larger, staying outside it) after Earth and the Spacecraft group (Tony\'s ruling of 2026-10-26, L-443, with the class check documentation/CHECK_L443_drawer_classes_20261026.md in the orrery). The comets on open paths are two groups after them, Hyperbolic comets (JPL\'s HYP) and Interstellar objects (the IAU\'s I numbers); piece C of C/2025 K1, which JPL classes as a comet, is in Comets. The Spacecraft group follows Earth\'s row, as the comets follow the Sun (Tony\'s ruling of 2026-10-24, L-443). Tony\'s ruling of 2026-10-22 (L-443): groups fold open in the drawer, and a room is for a body with more than its symbol. A row may carry the words a visitor sees for it: label, the name shown in the drawer and text box when it is not the served name; about, a sentence shown in the text box and the panel; source_note, what the Horizons id in the source line is. Tony\'s rulings, 2026-09-29 and 2026-09-30 (L-363). A GROUP row\'s about says in plain words what JPL\'s or the IAU\'s name for the class means, the name kept (Tony\'s rulings of 2026-10-26, \\"keep these correct words and explain them\\" and his approval of documentation/WORDS_L443_glosses_20261026.md in the orrery); it shows as the first bullet in the text box and the panel of every body in the group.",', 'interactive.html': "        underscore, C/2025_K1, is shown with JPL's space. Later the same", 'tools/headless/walk_solar_system_drawer.js': "// 3I/ATLAS's whole path, and Reset. Later that day: each group's class"}
POST_CALLS = []


def fail(msg):
    print(msg)
    print("NOTHING was written. Undo is not needed.")
    sys.exit(1)


def needs_patch_21():
    path = os.path.join(HERE, "data", "objects_config.json")
    if os.path.isfile(path):
        text = open(path, "rb").read().decode("utf-8")
        if '"group": "comets_hyp"' not in text:
            fail("ERROR: run patch_L443_21_comets_room_20261026.py first; "
                 "this patch explains the groups it adds.")


def main():
    needs_patch_21()
    same_new = set()
    for rel, content in NEW_FILES:
        full = os.path.join(HERE, *rel.split("/"))
        if os.path.exists(full):
            have = open(full, "rb").read().replace(b"\r\n", b"\n")
            if have == content.encode("utf-8"):
                same_new.add(rel)
                continue
            fail("ERROR: %s already exists and differs from what this patch "
                 "writes. Most likely a copy of the same document saved from "
                 "a download or an attachment: delete it and run this patch "
                 "again." % rel)
    staged = []
    for rel, edits in EDITS:
        path = os.path.join(HERE, *rel.split("/"))
        if not os.path.isfile(path):
            fail("ERROR: not found: %s -- is this file in the right folder?"
                 % path)
        raw = open(path, "rb").read()
        crlf = b"\r\n" in raw
        text = raw.replace(b"\r\n", b"\n").decode("utf-8")
        if SENTINELS.get(rel) and SENTINELS[rel] in text:
            fail("ERROR: %s already carries this patch's change; this "
                 "patch has run." % rel)
        for k, (old, new) in enumerate(edits):
            n = text.count(old)
            if n != 1:
                if new and text.count(new) == 1 and old not in text:
                    fail("ERROR: %s already carries edit %d of %d; this "
                         "patch has run." % (rel, k + 1, len(edits)))
                fail("ANCHOR FAIL in %s, edit %d of %d: expected 1 match, "
                     "found %d" % (rel, k + 1, len(edits), n))
            text = text.replace(old, new)
        staged.append((rel, path, text, crlf, len(edits)))
    for rel, path, text, crlf, n in staged:
        open(path, "wb").write(text.encode("utf-8"))
        print("ok  %s (%d edits)" % (rel, n))
        if crlf:
            print("note: %s was CRLF in the working copy; written LF" % rel)
        bad = sum(1 for c in text if ord(c) > 127)
        if bad:
            print("note: %s holds %d non-ASCII character(s) this patch did "
                  "not add" % (rel, bad))
    for rel, content in NEW_FILES:
        full = os.path.join(HERE, *rel.split("/"))
        if rel in same_new:
            print("ok  %s: already there, identical" % rel)
            continue
        d = os.path.dirname(full)
        if d and not os.path.isdir(d):
            os.makedirs(d)
        open(full, "wb").write(content.encode("utf-8"))
        print("ok  %s: new" % rel)
    for name in POST_CALLS:
        for line in globals()[name](HERE):
            print(line)
    print(DONE % (len(staged), len(NEW_FILES)))


if __name__ == "__main__":
    main()
